/*
 * Conformance test for DSA keys, methods, signatures, and generation (DSA_new(3),
 * DSA_meth_new(3), DSA_sign(3), DSA_do_sign(3), DSA_SIG_new(3), DSA_generate_parameters(3),
 * DSA_generate_key(3), DSA_dup_DH(3)), in TAP format: an empty key's sizes and flags, setting
 * and getting its numbers and the references the application holds, application data;
 * parameters generated by FIPS 186-2 and 186-4 (with and without a seed, with the old and new
 * callbacks); key generation; signatures and their verification (DER, exactly DER, long and
 * short digests, tampered signatures and digests, bad parameters and missing keys);
 * DSA_SIG's accessors and DER; methods (new, copy, rename, every function's getter and
 * setter, a counting method wrapping the built-in one, custom exponentiations, the default
 * method); and DSA_dup_DH.
 *
 * Everything runs on a known DRBG, so primes, keys, and signatures are printed (as their bits
 * and a hash) and must match the reference's.
 *
 * Built once against the vendored headers, then run against the reference OpenSSL and against
 * rustyssl: it must pass on both with the same output (TEST_PLAN.md, layer L4).
 */
#define OPENSSL_SUPPRESS_DEPRECATED
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <openssl/bn.h>
#include <openssl/core_names.h>
#include <openssl/dh.h>
#include <openssl/dsa.h>
#include <openssl/err.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

static int failures = 0;
static int number = 0;

static void check(int ok, const char *what)
{
    number++;
    if (!ok)
        failures++;
    printf("%s %d - %s\n", ok ? "ok" : "not ok", number, what);
}

static void errors(void)
{
    unsigned long e;
    const char *data;
    int flags;

    printf("  errors:");
    while ((e = ERR_get_error_all(NULL, NULL, NULL, &data, &flags)) != 0) {
        printf(" %d/%d", ERR_GET_LIB(e), ERR_GET_REASON(e));
        if ((flags & ERR_TXT_STRING) != 0 && data != NULL && *data != '\0')
            printf(" [%s]", data);
    }
    printf("\n");
}

/* A CTR-DRBG under a TEST-RAND parent with known entropy and nonce. */
static EVP_RAND_CTX *known_drbg(unsigned char seed)
{
    EVP_RAND *rand = EVP_RAND_fetch(NULL, "TEST-RAND", NULL);
    EVP_RAND_CTX *parent = EVP_RAND_CTX_new(rand, NULL), *ctx;
    unsigned char entropy[64], nonce[32];
    unsigned int strength = 256;
    OSSL_PARAM params[4];

    EVP_RAND_free(rand);
    memset(entropy, seed, sizeof(entropy));
    memset(nonce, seed ^ 0x5a, sizeof(nonce));
    params[0] = OSSL_PARAM_construct_uint(OSSL_RAND_PARAM_STRENGTH, &strength);
    params[1] = OSSL_PARAM_construct_octet_string(OSSL_RAND_PARAM_TEST_ENTROPY, entropy,
                                                  sizeof(entropy));
    params[2] = OSSL_PARAM_construct_octet_string(OSSL_RAND_PARAM_TEST_NONCE, nonce,
                                                  sizeof(nonce));
    params[3] = OSSL_PARAM_construct_end();
    EVP_RAND_instantiate(parent, 256, 0, NULL, 0, params);
    rand = EVP_RAND_fetch(NULL, "CTR-DRBG", NULL);
    ctx = EVP_RAND_CTX_new(rand, parent);
    EVP_RAND_free(rand);
    EVP_RAND_CTX_free(parent);
    params[0] = OSSL_PARAM_construct_utf8_string(OSSL_DRBG_PARAM_CIPHER, "AES-256-CTR", 0);
    params[1] = OSSL_PARAM_construct_end();
    if (!EVP_RAND_instantiate(ctx, 256, 0, NULL, 0, params)) {
        EVP_RAND_CTX_free(ctx);
        return NULL;
    }
    return ctx;
}

static void known_rand(unsigned char seed)
{
    RAND_set0_public(NULL, known_drbg(seed));
    RAND_set0_private(NULL, known_drbg(seed + 1));
}

static void octets(const char *label, const unsigned char *p, size_t n)
{
    unsigned char d[32];
    unsigned int dl = 0;
    size_t i;

    EVP_Digest(p, n, d, &dl, EVP_sha256(), NULL);
    printf("  %s (%zu):", label, n);
    for (i = 0; i < n && i < 8; i++)
        printf("%02x", p[i]);
    printf(" sha256 ");
    for (i = 0; i < 8; i++)
        printf("%02x", d[i]);
    printf("\n");
}

static void num(const char *label, const BIGNUM *b)
{
    unsigned char buf[1100];
    int n;

    if (b == NULL) {
        printf("  %s: (null)\n", label);
        return;
    }
    if (BN_num_bits(b) <= 64) {
        char *h = BN_bn2hex(b);

        printf("  %s: %d bits %s\n", label, BN_num_bits(b), h);
        OPENSSL_free(h);
        return;
    }
    n = BN_bn2bin(b, buf);
    printf("  %s: %d bits\n", label, BN_num_bits(b));
    octets("  octets", buf, (size_t)n);
}

static void show(const char *label, const DSA *d)
{
    printf("  %s: bits %d size %d security %d flags %#x\n", label, DSA_bits(d), DSA_size(d),
           DSA_security_bits(d), DSA_test_flags(d, ~0));
    num("p", DSA_get0_p(d));
    num("q", DSA_get0_q(d));
    num("g", DSA_get0_g(d));
    num("pub", DSA_get0_pub_key(d));
    num("priv", DSA_get0_priv_key(d));
}

static BIGNUM *hexbn(const char *h)
{
    BIGNUM *b = NULL;

    BN_hex2bn(&b, h);
    return b;
}

static void test_object(void)
{
    DSA *d = DSA_new();
    const BIGNUM *p, *q, *g, *pub, *priv;
    int idx;

    check(d != NULL, "an empty key");
    show("empty", d);
    printf("  method %s engine %p same as default %d\n", DSA_meth_get0_name(DSA_get_method(d)),
           (void *)DSA_get0_engine(d), DSA_get_method(d) == DSA_get_default_method());
    printf("  set0_pqg without q %d", DSA_set0_pqg(d, hexbn("17"), NULL, hexbn("5")));
    errors();
    p = hexbn("F7E75FDC469067FFDC4E847C51F452DF");
    q = hexbn("7BF3AFEE234833FF");
    g = hexbn("05");
    printf("  set0_pqg %d", DSA_set0_pqg(d, (BIGNUM *)p, (BIGNUM *)q, (BIGNUM *)g));
    printf(" same pointers %d %d %d\n", DSA_get0_p(d) == p, DSA_get0_q(d) == q,
           DSA_get0_g(d) == g);
    printf("  only g %d", DSA_set0_pqg(d, NULL, NULL, hexbn("07")));
    printf(" p kept %d\n", DSA_get0_p(d) == p);
    printf("  set0_key %d", DSA_set0_key(d, hexbn("1234"), NULL));
    printf(" %d", DSA_set0_key(d, NULL, hexbn("42")));
    printf(" %d\n", DSA_set0_key(d, NULL, NULL));
    DSA_get0_key(d, &pub, &priv);
    printf("  key same %d %d\n", DSA_get0_pub_key(d) == pub, DSA_get0_priv_key(d) == priv);
    show("made up", d);
    DSA_get0_pqg(d, &p, NULL, NULL);
    printf("  get0_pqg p %d\n", p == DSA_get0_p(d));

    DSA_clear_flags(d, DSA_FLAG_CACHE_MONT_P);
    DSA_set_flags(d, 0x1000);
    printf("  flags %#x\n", DSA_test_flags(d, ~0));
    idx = DSA_get_ex_new_index(0, "test", NULL, NULL, NULL);
    printf("  ex_data %d %s\n", DSA_set_ex_data(d, idx, "hello"),
           (const char *)DSA_get_ex_data(d, idx));
    printf("  up_ref %d\n", DSA_up_ref(d));
    DSA_free(d);
    show("still", d);
    DSA_free(d);
    DSA_free(NULL);
    d = DSA_new_method(NULL);
    printf("  new_method %d flags %#x\n", d != NULL, DSA_test_flags(d, ~0));
    DSA_free(d);
    errors();
}

static int gencb_calls = 0;

static int gencb(int a, int b, BN_GENCB *cb)
{
    (void)a;
    (void)b;
    (void)cb;
    gencb_calls++;
    return 1;
}

static int old_calls = 0;

static void old_cb(int a, int b, void *arg)
{
    (void)a;
    (void)b;
    (void)arg;
    old_calls++;
}

static DSA *params1024(void)
{
    DSA *d = DSA_new();
    BN_GENCB *cb = BN_GENCB_new();
    int counter = -7;
    unsigned long h = 7;

    BN_GENCB_set(cb, gencb, NULL);
    printf("  generate 1024 %d", DSA_generate_parameters_ex(d, 1024, NULL, 0, &counter, &h, cb));
    printf(" counter %d h %lu calls>0 %d\n", counter, h, gencb_calls > 0);
    BN_GENCB_free(cb);
    errors();
    return d;
}

static void test_generate(void)
{
    DSA *d, *e;
    unsigned char seed[32];
    int counter = -7;
    unsigned long h = 7;

    known_rand(51);
    d = params1024();
    check(d != NULL, "parameter generation");
    show("186-2", d);
    printf("  key %d\n", DSA_generate_key(d));
    show("with a key", d);
    printf("  again %d\n", DSA_generate_key(d));
    num("new priv", DSA_get0_priv_key(d));
    errors();
    DSA_free(d);

    memset(seed, 0x42, sizeof(seed));
    d = DSA_new();
    printf("  seed 32 %d", DSA_generate_parameters_ex(d, 1024, seed, 32, &counter, &h, NULL));
    printf(" counter %d h %lu\n", counter, h);
    errors();
    show("186-4 seeded", d);
    DSA_free(d);
    d = DSA_new();
    printf("  seed 20 %d", DSA_generate_parameters_ex(d, 1024, seed, 20, &counter, &h, NULL));
    printf(" counter %d h %lu\n", counter, h);
    errors();
    show("186-2 seeded", d);
    DSA_free(d);
    d = DSA_new();
    printf("  512 bits %d", DSA_generate_parameters_ex(d, 512, NULL, 0, NULL, NULL, NULL));
    errors();
    DSA_free(d);
    e = DSA_generate_parameters(1024, NULL, 0, &counter, NULL, old_cb, NULL);
    printf("  old %d counter %d calls>0 %d\n", e != NULL, counter, old_calls > 0);
    errors();
    DSA_free(e);

    d = DSA_new();
    printf("  key without parameters %d", DSA_generate_key(d));
    errors();
    DSA_free(d);
}

static void sign_verify(DSA *d, const unsigned char *dgst, int dlen, const char *label)
{
    unsigned char sig[200];
    unsigned int siglen = 0;
    int r;

    r = DSA_sign(0, dgst, dlen, sig, &siglen, d);
    printf("  %s: sign %d len %u", label, r, siglen);
    if (r == 1) {
        printf("\n");
        octets("sig", sig, siglen);
        printf("  verify %d", DSA_verify(0, dgst, dlen, sig, (int)siglen, d));
        sig[siglen - 1] ^= 1;
        printf(" tampered %d", DSA_verify(0, dgst, dlen, sig, (int)siglen, d));
        sig[siglen - 1] ^= 1;
        sig[siglen] = 0;
        printf(" trailing %d", DSA_verify(0, dgst, dlen, sig, (int)siglen + 1, d));
        printf(" short %d\n", DSA_verify(0, dgst, dlen, sig, (int)siglen - 1, d));
    } else {
        printf("\n");
    }
    errors();
}

static void test_sign(void)
{
    DSA *d;
    unsigned char dgst[64];
    unsigned int siglen = 0;
    DSA_SIG *s;
    const BIGNUM *r, *sv;
    int i;

    for (i = 0; i < 64; i++)
        dgst[i] = (unsigned char)(i * 7 + 3);
    known_rand(61);
    d = params1024();
    DSA_generate_key(d);
    check(d != NULL, "signatures");
    printf("  size query %d", DSA_sign(0, dgst, 20, NULL, &siglen, d));
    printf(" %u size %d\n", siglen, DSA_size(d));
    sign_verify(d, dgst, 20, "20 octets");
    sign_verify(d, dgst, 32, "32 octets");
    sign_verify(d, dgst, 64, "64 octets");
    sign_verify(d, dgst, 1, "1 octet");
    sign_verify(d, dgst, 0, "no digest");

    s = DSA_do_sign(dgst, 20, d);
    DSA_SIG_get0(s, &r, &sv);
    num("r", r);
    num("s", sv);
    printf("  do_verify %d", DSA_do_verify(dgst, 20, s, d));
    dgst[0] ^= 1;
    printf(" other digest %d\n", DSA_do_verify(dgst, 20, s, d));
    dgst[0] ^= 1;
    {
        BIGNUM *zero = BN_new(), *big = BN_dup(DSA_get0_q(d));
        DSA_SIG *t = DSA_SIG_new();

        BN_zero(zero);
        DSA_SIG_set0(t, zero, BN_dup(sv));
        printf("  r 0 %d", DSA_do_verify(dgst, 20, t, d));
        DSA_SIG_set0(t, big, BN_dup(sv));
        printf(" r q %d\n", DSA_do_verify(dgst, 20, t, d));
        DSA_SIG_free(t);
    }
    errors();
    DSA_SIG_free(s);

    {
        BIGNUM *kinv = NULL, *rr = BN_new();

        printf("  sign_setup %d", DSA_sign_setup(d, NULL, &kinv, &rr));
        printf(" kinv %d r %d\n", BN_num_bits(kinv) > 0, BN_num_bits(rr) > 0);
        BN_free(kinv);
        BN_free(rr);
        errors();
    }

    /* Without a private key, without parameters, with a q of a bad size. */
    {
        DSA *pub = DSA_new();
        unsigned char sig[200];
        unsigned int n = 0;

        DSA_set0_pqg(pub, BN_dup(DSA_get0_p(d)), BN_dup(DSA_get0_q(d)), BN_dup(DSA_get0_g(d)));
        DSA_set0_key(pub, BN_dup(DSA_get0_pub_key(d)), NULL);
        printf("  public only: sign %d", DSA_sign(0, dgst, 20, sig, &n, pub));
        printf(" len %u", n);
        errors();
        DSA_free(pub);
        pub = DSA_new();
        printf("  empty: sign %d", DSA_sign(0, dgst, 20, sig, &n, pub));
        errors();
        s = DSA_do_sign(dgst, 20, d);
        printf("  verify empty %d", DSA_do_verify(dgst, 20, s, pub));
        errors();
        DSA_set0_pqg(pub, hexbn("F7E75FDC469067FFDC4E847C51F452DF"), hexbn("7BF3AFEE234833FF"),
                     hexbn("05"));
        DSA_set0_key(pub, hexbn("1234"), hexbn("42"));
        printf("  small q: verify %d", DSA_do_verify(dgst, 20, s, pub));
        errors();
        printf("  small q: sign %d", DSA_sign(0, dgst, 20, sig, &n, pub));
        errors();
        DSA_SIG_free(s);
        DSA_free(pub);
    }
    DSA_free(d);
}

static void test_sig(void)
{
    DSA_SIG *s = DSA_SIG_new(), *t = NULL;
    const BIGNUM *r = (const BIGNUM *)1, *sv = (const BIGNUM *)1;
    unsigned char *der = NULL;
    const unsigned char *pp;
    int n;
    static const unsigned char bad[] = { 0x30, 0x06, 0x02, 0x01, 0x05, 0x02, 0x01 };
    static const unsigned char good[] = { 0x30, 0x06, 0x02, 0x01, 0x05, 0x02, 0x01, 0x07 };

    check(s != NULL, "DSA_SIG");
    DSA_SIG_get0(s, &r, &sv);
    printf("  empty %p %p", (void *)r, (void *)sv);
    errors();
    printf("  set0 NULL %d", DSA_SIG_set0(s, NULL, BN_new()));
    printf(" set0 %d\n", DSA_SIG_set0(s, hexbn("05"), hexbn("07")));
    n = i2d_DSA_SIG(s, &der);
    octets("der", der, (size_t)n);
    pp = der;
    t = d2i_DSA_SIG(NULL, &pp, n);
    DSA_SIG_get0(t, &r, &sv);
    printf("  back consumed %ld r %s", (long)(pp - der), BN_bn2hex(r));
    printf("\n");
    DSA_SIG_free(t);
    t = NULL;
    pp = bad;
    printf("  truncated %d", d2i_DSA_SIG(&t, &pp, sizeof(bad)) != NULL);
    pp = good;
    printf(" negative length %d", d2i_DSA_SIG(NULL, &pp, -1) != NULL);
    printf(" good %d\n", d2i_DSA_SIG(&s, &pp, sizeof(good)) == s);
    errors();
    OPENSSL_free(der);
    DSA_SIG_free(s);
    DSA_SIG_free(t);
}

/* A method that counts what it's asked to do, calling the built-in functions. */
static int signs = 0, verifies = 0, setups = 0, inits = 0, finishes = 0, exps = 0, exp2s = 0;
static DSA_SIG *(*orig_sign)(const unsigned char *, int, DSA *);
static int (*orig_verify)(const unsigned char *, int, DSA_SIG *, DSA *);
static int (*orig_setup)(DSA *, BN_CTX *, BIGNUM **, BIGNUM **);

static DSA_SIG *count_sign(const unsigned char *d, int n, DSA *dsa)
{
    signs++;
    return orig_sign(d, n, dsa);
}

static int count_verify(const unsigned char *d, int n, DSA_SIG *s, DSA *dsa)
{
    verifies++;
    return orig_verify(d, n, s, dsa);
}

static int count_setup(DSA *dsa, BN_CTX *ctx, BIGNUM **k, BIGNUM **r)
{
    setups++;
    return orig_setup(dsa, ctx, k, r);
}

static int count_init(DSA *dsa)
{
    (void)dsa;
    inits++;
    return 1;
}

static int count_finish(DSA *dsa)
{
    (void)dsa;
    finishes++;
    return 1;
}

static int my_exp(DSA *dsa, BIGNUM *r, const BIGNUM *a, const BIGNUM *p, const BIGNUM *m,
                  BN_CTX *ctx, BN_MONT_CTX *mont)
{
    (void)dsa;
    (void)mont;
    exps++;
    return BN_mod_exp(r, a, p, m, ctx);
}

static int my_exp2(DSA *dsa, BIGNUM *rr, const BIGNUM *a1, const BIGNUM *p1, const BIGNUM *a2,
                   const BIGNUM *p2, const BIGNUM *m, BN_CTX *ctx, BN_MONT_CTX *mont)
{
    BN_CTX *c = BN_CTX_new();
    BIGNUM *t = BN_new();
    int ok;

    (void)dsa;
    (void)ctx;
    (void)mont;
    exp2s++;
    ok = BN_mod_exp(rr, a1, p1, m, c) && BN_mod_exp(t, a2, p2, m, c)
         && BN_mod_mul(rr, rr, t, m, c);
    BN_free(t);
    BN_CTX_free(c);
    return ok;
}

static void test_meth(void)
{
    DSA_METHOD *m = DSA_meth_new("counting", DSA_FLAG_FIPS_METHOD), *m2;
    const DSA_METHOD *ossl = DSA_OpenSSL();
    DSA *d, *k;
    unsigned char dgst[20] = { 1, 2, 3 };
    unsigned char sig[100];
    unsigned int n = 0;

    check(m != NULL, "methods");
    printf("  name %s flags %#x\n", DSA_meth_get0_name(m), DSA_meth_get_flags(m));
    printf("  builtin %s flags %#x sign %d setup %d verify %d mod_exp %d bn_mod_exp %d init %d "
           "finish %d paramgen %d keygen %d\n",
           DSA_meth_get0_name(ossl), DSA_meth_get_flags(ossl), DSA_meth_get_sign(ossl) != NULL,
           DSA_meth_get_sign_setup(ossl) != NULL, DSA_meth_get_verify(ossl) != NULL,
           DSA_meth_get_mod_exp(ossl) != NULL, DSA_meth_get_bn_mod_exp(ossl) != NULL,
           DSA_meth_get_init(ossl) != NULL, DSA_meth_get_finish(ossl) != NULL,
           DSA_meth_get_paramgen(ossl) != NULL, DSA_meth_get_keygen(ossl) != NULL);
    orig_sign = DSA_meth_get_sign(ossl);
    orig_verify = DSA_meth_get_verify(ossl);
    orig_setup = DSA_meth_get_sign_setup(ossl);
    printf("  set %d", DSA_meth_set_sign(m, count_sign));
    printf(" %d", DSA_meth_set_verify(m, count_verify));
    printf(" %d", DSA_meth_set_sign_setup(m, count_setup));
    printf(" %d", DSA_meth_set_init(m, count_init));
    printf(" %d", DSA_meth_set_finish(m, count_finish));
    printf(" %d", DSA_meth_set_bn_mod_exp(m, my_exp));
    printf(" %d", DSA_meth_set_mod_exp(m, my_exp2));
    printf(" %d", DSA_meth_set_paramgen(m, NULL));
    printf(" %d", DSA_meth_set_keygen(m, NULL));
    printf(" %d", DSA_meth_set1_name(m, "renamed"));
    printf(" %d", DSA_meth_set0_app_data(m, (void *)m));
    printf(" %d\n", DSA_meth_set_flags(m, 0));
    printf("  name %s data %d\n", DSA_meth_get0_name(m), DSA_meth_get0_app_data(m) == (void *)m);
    m2 = DSA_meth_dup(m);
    printf("  dup %s same sign %d\n", DSA_meth_get0_name(m2), DSA_meth_get_sign(m2) == count_sign);
    DSA_meth_free(m2);

    known_rand(71);
    d = params1024();
    DSA_generate_key(d);
    printf("  set_method %d inits %d flags %#x\n", DSA_set_method(d, m), inits,
           DSA_test_flags(d, ~0));
    printf("  sign %d", DSA_sign(0, dgst, 20, sig, &n, d));
    octets("sig", sig, n);
    printf("  verify %d", DSA_verify(0, dgst, 20, sig, (int)n, d));
    printf(" signs %d verifies %d setups %d exps %d exp2s %d\n", signs, verifies, setups, exps,
           exp2s);
    errors();

    /* As the default method, for new keys. */
    DSA_set_default_method(m);
    k = DSA_new();
    printf("  new key's method %s inits %d flags %#x\n", DSA_meth_get0_name(DSA_get_method(k)),
           inits, DSA_test_flags(k, ~0));
    DSA_free(k);
    printf("  finishes %d\n", finishes);
    DSA_set_default_method(ossl);
    DSA_set_method(d, ossl);
    printf("  back finishes %d flags %#x\n", finishes, DSA_test_flags(d, ~0));
    DSA_free(d);
    DSA_meth_free(m);
    errors();
}

static void test_dup_dh(void)
{
    DSA *d;
    DH *h;
    const BIGNUM *p, *q, *g;

    known_rand(81);
    d = params1024();
    check(d != NULL, "DSA_dup_DH");
    h = DSA_dup_DH(d);
    DH_get0_pqg(h, &p, &q, &g);
    printf("  params %d %d %d key %d\n", BN_cmp(p, DSA_get0_p(d)) == 0,
           BN_cmp(q, DSA_get0_q(d)) == 0, BN_cmp(g, DSA_get0_g(d)) == 0,
           DH_get0_pub_key(h) != NULL);
    DH_free(h);
    DSA_generate_key(d);
    h = DSA_dup_DH(d);
    printf("  keys %d %d\n", BN_cmp(DH_get0_pub_key(h), DSA_get0_pub_key(d)) == 0,
           BN_cmp(DH_get0_priv_key(h), DSA_get0_priv_key(d)) == 0);
    DH_free(h);
    DSA_set0_key(d, NULL, NULL);
    printf("  NULL %p\n", (void *)DSA_dup_DH(NULL));
    errors();
    DSA_free(d);
}

int main(void)
{
    test_object();
    test_generate();
    test_sign();
    test_sig();
    test_meth();
    test_dup_dh();
    errors();
    printf("1..%d\n", number);
    return failures == 0 ? 0 : 1;
}
